const workspaceDefinitions={visual:{taskType:'image_creation',accept:'image/jpeg,image/png,image/webp',maxBytes:20*1024*1024,preview:'image',zh:{title:'视觉与海报',description:'上传一张图片，或从一个想法开始。我们会先帮助你准备可用的视觉方向、文案与提示词。',upload:'上传图片',drop:'拖放 JPG、PNG 或 WEBP 图片到这里',formats:'最大 20 MB。图片只保留在当前浏览器会话中。',prompt:'你想创作什么图片或海报？',submit:'准备视觉方案',saved:'已保存到项目。',local:'已在本机选择：',fileOnly:'图片已在本机选择；目前不会上传或分析其像素内容。请描述你想修改或创作的内容。'},en:{title:'Visuals & posters',description:'Upload an image or start from an idea. We will help prepare visual direction, copy, and a usable prompt.',upload:'Upload image',drop:'Drop a JPG, PNG, or WEBP image here',formats:'Maximum 20 MB. The image stays in this browser session.',prompt:'What image or poster would you like to create?',submit:'Prepare visual plan',saved:'Saved to your project.',local:'Selected locally: ',fileOnly:'The image is selected locally; its pixels are not uploaded or analyzed yet. Describe what you want to change or create.'}},writing:{taskType:'writing',accept:'.txt,.md,.csv,.pdf,.doc,.docx,text/plain,text/markdown,text/csv,application/pdf,application/msword,application/vnd.openxmlformats-officedocument.wordprocessingml.document',maxBytes:20*1024*1024,preview:'none',zh:{title:'写作与方案',description:'写文章、做计划、改文案或翻译。可选择参考文件；目前会保留在你的设备上。',upload:'选择参考文件',drop:'拖放 TXT、MD、CSV、PDF、DOC 或 DOCX 文件',formats:'最大 20 MB。文件不会默认上传或公开存储。',prompt:'你想写什么或规划什么？',submit:'开始写作',saved:'已保存到项目。',local:'已在本机选择：',fileOnly:'参考文件已在本机选择；请在任务中说明需要如何使用它。'},en:{title:'Writing & plans',description:'Write, plan, revise, translate, or summarize. You may select a reference file; it remains on your device for now.',upload:'Choose reference file',drop:'Drop a TXT, MD, CSV, PDF, DOC, or DOCX file here',formats:'Maximum 20 MB. Files are not uploaded or placed in public storage.',prompt:'What would you like to write or plan?',submit:'Start writing',saved:'Saved to your project.',local:'Selected locally: ',fileOnly:'The reference file is selected locally. Tell AI how you would like to use it.'}},presentation:{taskType:'presentation',accept:'.pdf,.docx,.pptx,application/pdf,application/vnd.openxmlformats-officedocument.wordprocessingml.document,application/vnd.openxmlformats-officedocument.presentationml.presentation',maxBytes:20*1024*1024,preview:'none',zh:{title:'演示与汇报',description:'从一个主题或参考材料开始，准备清晰的 PPT 结构、逐页要点和讲述内容。',upload:'上传参考文件',drop:'拖放 PDF、DOCX 或 PPTX 文件到这里',formats:'最大 20 MB。当前会准备大纲与内容，不会生成 PPTX 文件。',prompt:'你想制作什么样的演示文稿？',submit:'准备演示大纲',saved:'已保存到项目。',local:'已在本机选择：',fileOnly:'参考文件已在本机选择；当前不会上传或读取文件内容。请描述你希望制作或改进的演示。'},en:{title:'Presentations',description:'Start with a topic or reference material and prepare a clear slide structure, slide copy, and speaking notes.',upload:'Upload reference file',drop:'Drop a PDF, DOCX, or PPTX file here',formats:'Maximum 20 MB. AI prepares outline and content; it does not generate a PPTX file yet.',prompt:'What presentation would you like to create?',submit:'Prepare presentation outline',saved:'Saved to your project.',local:'Selected locally: ',fileOnly:'The reference file is selected locally. Its contents are not uploaded or read yet; describe the presentation you want to make or improve.'}},video:{taskType:'video',accept:'video/*',maxBytes:80*1024*1024,preview:'video',zh:{title:'视频与短片',description:'上传视频或描述你的想法。先准备脚本、分镜、字幕建议和剪辑方向。',upload:'上传视频',drop:'拖放视频文件到这里',formats:'最大 80 MB。视频只保留在当前浏览器会话中。',prompt:'你想制作什么视频或音频内容？',submit:'准备视频方案',saved:'已保存到项目。',local:'已在本机选择：',fileOnly:'视频已在本机选择；目前不会上传或分析其画面和音频。请描述你希望分析、修改或创作的内容。'},en:{title:'Video & shorts',description:'Upload a video or describe an idea. Start with a script, storyboard, caption suggestions, and editing direction.',upload:'Upload video',drop:'Drop a video file here',formats:'Maximum 80 MB. The video stays in this browser session.',prompt:'What video or audio would you like to create?',submit:'Prepare video plan',saved:'Saved to your project.',local:'Selected locally: ',fileOnly:'The video is selected locally; its visuals and audio are not uploaded or analyzed yet. Describe what you want to analyze, change, or create.'}}};
const workspace=document.body.dataset.workspace;const definition=workspaceDefinitions[workspace];const shared={zh:{panelTitle:'告诉 AI 你想完成什么',panelCopy:'你的任务会保留在这一条对话中。',taskLabel:'你的任务',save:'保存到项目',resultsTitle:'AI SuperMall',resultsCopy:'继续补充或修改，让任务一步步完成。',note:'所选文件只保留在当前浏览器会话中，直到安全的专用工具接入。',choose:'选择文件',addMoreImages:'添加更多图片'},en:{panelTitle:'Tell AI what you want to accomplish',panelCopy:'Your task stays in this one conversation.',taskLabel:'Your task',save:'Save to Project',resultsTitle:'AI SuperMall',resultsCopy:'Keep refining the work in this conversation.',note:'Selected files remain only in this browser session until a secure specialist tool is connected.',choose:'Choose file',addMoreImages:'Add more images'}};let language=localStorage.getItem('ai-supermall-language')||'zh',selectedFile=null,selectedImages=[],objectUrl='',conversation=[],activeConversationId='',activeProjectId='',queue=Promise.resolve();const $=selector=>document.querySelector(selector);const text=()=>definition[language];const request=async(path,options={})=>{const response=await fetch(path,options);const body=await response.json().catch(()=>({}));if(!response.ok)throw new Error(body.error||'Request failed');return body};
function setStatus(message){$('#workspaceStatus').textContent=message||''}function renderHistory(){const list=$('#workspaceHistory');list.innerHTML='';conversation.forEach(item=>{const card=document.createElement('article'),question=document.createElement('strong'),answer=document.createElement('p');question.textContent=item.question;answer.textContent=item.answer;card.append(question,answer);list.append(card)});$('#workspaceResults').hidden=!conversation.length}function applyLanguage(next){language=next;localStorage.setItem('ai-supermall-language',next);document.documentElement.lang=next==='zh'?'zh-CN':'en';const t=text(),s=shared[next],taskPanel=$('#workspaceForm').closest('.workspace-panel');document.title=`AI SuperMall — ${t.title}`;$('#workspaceTitle').textContent=t.title;$('#workspaceDescription').textContent=t.description;$('#uploadLabel').textContent=t.upload;$('#dropText').textContent=t.drop;$('#formatText').textContent=t.formats;$('#uploadButton').textContent=s.choose;$('#taskInput').placeholder=t.prompt;$('#workspaceSubmit').textContent=t.submit;$('#saveProject').textContent=s.save;taskPanel.querySelector('h2').textContent=s.panelTitle;taskPanel.querySelector('p').textContent=s.panelCopy;taskPanel.querySelector('label').textContent=s.taskLabel;$('#workspaceResults').querySelector('h2').textContent=s.resultsTitle;$('#workspaceResults').querySelector('p').textContent=s.resultsCopy;$('.workspace-note').textContent=s.note;$('#homeLink').textContent=next==='zh'?'首页':'Home';$('#projectsLink').textContent=next==='zh'?'我的项目':'My Projects';$('#languageToggle').textContent=next==='zh'?'EN':'中文';if(workspace==='visual')renderImageAssets();else if(selectedFile)setStatus(`${t.local}${selectedFile.name}. ${t.fileOnly}`)}
function clearPreview(){if(objectUrl)URL.revokeObjectURL(objectUrl);objectUrl='';const preview=$('#filePreview');preview.removeAttribute('src');preview.classList.remove('show')}function isAccepted(file){return definition.accept.split(',').some(rule=>rule==='video/*'?file.type.startsWith('video/'):rule.startsWith('.')?file.name.toLowerCase().endsWith(rule):file.type===rule)}function fileKey(file){return `${file.name}:${file.size}:${file.lastModified}`}function ensureImageAssets(){if(workspace!=='visual')return null;let assets=$('#imageAssets');if(assets)return assets;assets=document.createElement('section');assets.className='image-assets';assets.id='imageAssets';const heading=document.createElement('div'),title=document.createElement('strong'),clear=document.createElement('button'),grid=document.createElement('div');heading.className='image-assets-heading';title.id='imageAssetsTitle';clear.id='clearImages';clear.type='button';grid.className='image-assets-grid';grid.id='imageAssetsGrid';heading.append(title,clear);assets.append(heading,grid);$('#workspaceStatus').insertAdjacentElement('afterend',assets);clear.addEventListener('click',clearImages);return assets}function renderImageAssets(){const assets=ensureImageAssets();if(!assets)return;const zh=language==='zh',grid=$('#imageAssetsGrid'),clear=$('#clearImages');$('#imageAssetsTitle').textContent=zh?`已选图片（${selectedImages.length}/10）`:`Selected images (${selectedImages.length}/10)`;clear.textContent=zh?'全部清除':'Clear all';clear.hidden=!selectedImages.length;document.querySelector('#uploadButton').textContent=selectedImages.length?s.addMoreImages:s.choose;grid.innerHTML='';selectedImages.forEach(item=>{const card=document.createElement('article'),image=document.createElement('img'),name=document.createElement('span'),size=document.createElement('small'),remove=document.createElement('button');image.src=item.url;image.alt=item.file.name;name.textContent=item.file.name;size.textContent=`${(item.file.size/1024/1024).toFixed(1)} MB`;remove.type='button';remove.textContent=zh?'删除':'Remove';remove.addEventListener('click',()=>removeImage(item.key));card.append(image,name,size,remove);grid.append(card)});assets.hidden=!selectedImages.length}function removeImage(key){const index=selectedImages.findIndex(item=>item.key===key);if(index<0)return;URL.revokeObjectURL(selectedImages[index].url);selectedImages.splice(index,1);renderImageAssets()}function clearImages(){selectedImages.forEach(item=>URL.revokeObjectURL(item.url));selectedImages=[];renderImageAssets();setStatus('')}function appendImages(files){const zh=language==='zh', t=text();let added=0,duplicate=0,invalid=0,overLimit=0;for(const file of files){if(!file)continue;if(!isAccepted(file)||file.size>definition.maxBytes){invalid++;continue}if(selectedImages.some(item=>item.key===fileKey(file))){duplicate++;continue}if(selectedImages.length>=10){overLimit++;continue}selectedImages.push({file,key:fileKey(file),url:URL.createObjectURL(file)});added++}renderImageAssets();const messages=[];if(added)messages.push(zh?`已添加 ${added} 张图片。`:`${added} image${added===1?'':'s'} added.`);if(overLimit)messages.push(zh?'每个任务最多 10 张图片。':'A task can include up to 10 images.');if(invalid)messages.push(zh?'部分文件类型不支持或超过 20 MB。':'Some files are unsupported or exceed 20 MB.');if(duplicate)messages.push(zh?'已跳过重复图片。':'Duplicate images were skipped.');setStatus(messages.join(' '));$('#fileInput').value=''}function setFile(file){const t=text();if(!file)return;if(!isAccepted(file)){setStatus(language==='zh'?'此文件类型不受支持。':'This file type is not supported.');return}if(file.size>definition.maxBytes){setStatus(language==='zh'?`文件超过 ${Math.round(definition.maxBytes/1024/1024)} MB 限制。`:`File exceeds the ${Math.round(definition.maxBytes/1024/1024)} MB limit.`);return}selectedFile=file;clearPreview();const preview=$('#filePreview');if(definition.preview!=='none'){objectUrl=URL.createObjectURL(file);preview.src=objectUrl;preview.classList.add('show')}setStatus(`${t.local}${file.name}. ${t.fileOnly}`)}
$('#fileInput').accept=definition.accept;$('#fileInput').addEventListener('change',event=>{const files=[...event.target.files||[]];if(workspace==='visual')appendImages(files);else setFile(files[0])});const drop=$('#dropZone');['dragenter','dragover'].forEach(type=>drop.addEventListener(type,event=>{event.preventDefault();drop.classList.add('dragging')}));['dragleave','drop'].forEach(type=>drop.addEventListener(type,event=>{event.preventDefault();drop.classList.remove('dragging')}));drop.addEventListener('drop',event=>{const files=[...event.dataTransfer.files||[]];if(workspace==='visual')appendImages(files);else setFile(files[0])});
async function saveConversation(){if(!conversation.length||activeProjectId)return;const signedIn=(await fetch('/api/account/me')).ok;if(!signedIn)return;const existing=Boolean(activeConversationId);const body=existing?{id:activeConversationId,locale:language,messages:conversation}:{title:conversation[0].question.slice(0,120),locale:language,messages:conversation};const result=await request('/api/member/conversations',{method:existing?'PATCH':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});if(!existing){const saved=Array.isArray(result)?result[0]:result;activeConversationId=saved?.id||''}}
function scheduleConversationSave(){queue=queue.then(saveConversation).catch(()=>{});return queue}async function updateProject(){if(!activeProjectId)return;await request('/api/member/projects',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:activeProjectId,locale:language,conversation})})}
$('#workspaceForm').addEventListener('submit',async event=>{event.preventDefault();const question=$('#taskInput').value.trim();if(!question){$('#taskInput').focus();return}const submit=$('#workspaceSubmit');submit.disabled=true;setStatus(language==='zh'?'正在准备…':'Preparing…');try{const response=await request('/api/recommend',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({query:question,language,context:conversation.slice(-4),taskType:definition.taskType})});conversation.push({question,answer:response.answer||''});$('#taskInput').value='';renderHistory();setStatus('');if(activeProjectId)await updateProject();else scheduleConversationSave()}catch(error){setStatus(error.message||'Unable to complete this task.')}finally{submit.disabled=false;$('#taskInput').focus()}});
$('#saveProject').addEventListener('click',async()=>{if(!conversation.length)return;try{const me=await fetch('/api/account/me');if(!me.ok){location.href='account.html?mode=login';return}if(activeProjectId){await updateProject()}else{const result=await request('/api/member/projects',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({title:conversation[0].question.slice(0,120),locale:language,conversation})});const saved=Array.isArray(result)?result[0]:result;activeProjectId=saved?.id||'';activeConversationId=''}setStatus(text().saved)}catch(error){setStatus(error.message||'Unable to save project.')}});
$('#languageToggle').addEventListener('click',()=>applyLanguage(language==='zh'?'en':'zh'));applyLanguage(language);



